  VALUES ('devops', 'tr', 'mid', 'Blue-Green Deployment nedir?', 'Blue-Green: aktif (blue) + pasif (green) ortam. Yeni versiyon green''e deploy edilir, test edilir, sonra load balancer trafiği green''e yönlendirir. Sorun çıkarsa blue''ya anında geri dönülür. Zero-downtime deployment sağlar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
