UNION ALL
  SELECT id, 3, 'Automation, Concurrency, Indexing, Delivery' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('database', 'tr', 'mid', 'N+1 Query problemi nedir?', 'N+1: ORM''lerde sık karşılaşılır. 1 sorgu 10 post getirir, sonra her post için 1 sorgu comments getirir → 11 sorgu. Çözüm: eager loading (JOIN) veya ORM''de `include`/`with` kullanmak. Büyük veri setlerinde ciddi performans sorununa yol açar.', 1, true)
  RETURNING id
)
