  VALUES ('database', 'tr', 'mid', 'Database Replication nedir?', 'Replication: primary/master-replica/slave mimarisi. Primary''e yazılır, replica''lara asenkron/senkron kopyalanır. Avantajlar: read ölçeklendirme (replica''lardan okuma), yüksek erişilebilirlik (primary çökerse replica devreye girer), disaster recovery.', 2, true)
  RETURNING id
)
