WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('algorithms', 'tr', 'junior', 'Binary Search''ün time complexity''si nedir ve hangi ön koşulu vardır?', 'Binary Search her adımda arama alanını ikiye böler: O(log n). Ön koşul: dizi sıralı olmalıdır. 1 milyar elemanlı sıralı dizide maksimum ~30 adımda sonuca ulaşılır. Linear search ile karşılaştırıldığında (O(n)) büyük veri setlerinde dramatik fark yaratır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
