UNION ALL
  SELECT id, 1, 'O(log n), dizi sıralı olmalıdır' FROM q
UNION ALL
  SELECT id, 2, 'O(n log n), dizi sıralı olmalıdır' FROM q
UNION ALL
  SELECT id, 3, 'O(1), her zaman' FROM q;

