  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('algorithms', 'tr', 'mid', 'Quicksort''un ortalama (average case) time complexity''si nedir?', 'Quicksort average case: O(n log n). Worst case: O(n²) - pivot her seferinde en küçük/büyük seçilirse (sıralı dizi). Pivot seçimi (random, median-of-three) worst case''i önlemek için kritiktir. In-place çalıştığından cache-friendly''dir.', 1, true)
  RETURNING id
)
