WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('javascript', 'tr', 'mid', '`Promise.allSettled()` ile `Promise.all()` arasındaki fark nedir?', '`Promise.all([p1, p2, p3])` biri reject olursa diğerleri tamamlansa bile hemen reject eder ("fail fast"). `Promise.allSettled()` tümünü bekler, her biri için `{ status: "fulfilled", value }` veya `{ status: "rejected", reason }` döner. Bağımsız işlemleri toplu yaparken allSettled tercih edilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynı şekilde çalışır' FROM q
UNION ALL
  SELECT id, 1, '`Promise.all()` herhangi biri reject olursa hemen reject eder. `Promise.allSettled()` tümünün tamamlanmasını bekler; her biri için `{status, value/reason}` döner' FROM q
UNION ALL
  SELECT id, 2, '`Promise.allSettled()` daha yavaştır' FROM q
UNION ALL
  SELECT id, 3, '`Promise.allSettled()` sadece başarılı promise''leri döndürür' FROM q;

-- ── python (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'senior', 'Python''da GIL (Global Interpreter Lock) nedir?', 'GIL, CPython''un bellek yönetimini thread-safe tutmak için kullandığı bir kilittir. CPU-bound işler için threading yerine multiprocessing kullanılmalıdır (her process kendi GIL''ine sahiptir). I/O-bound işlerde GIL thread geçişleri sırasında serbest bırakıldığından threading hâlâ faydalıdır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Python''u daha hızlı çalıştıran bir optimizasyon' FROM q
UNION ALL
  SELECT id, 1, 'CPython''da aynı anda yalnızca bir thread''in bytecode çalıştırmasına izin veren bir mutex; multi-thread programlarda CPU-bound görevlerin paralel çalışmasını engeller' FROM q
UNION ALL
  SELECT id, 2, 'Sadece multiprocessing modülünü etkiler' FROM q
UNION ALL
  SELECT id, 3, 'Python 3''te kaldırılmıştır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'mid', 'Python decorator''ı nedir ve ne zaman kullanılır?', 'Decorator, `func = decorator(func)` işleminin kısa yoludur. Logging, authentication, caching (functools.lru_cache), timing gibi cross-cutting concern''leri temiz biçimde ekler. `@functools.wraps(func)` ile orijinal fonksiyonun `__name__` ve `__doc__` bilgileri korunur.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Sınıfları görsel olarak süsleyen bir araç' FROM q
UNION ALL
  SELECT id, 1, 'Bir fonksiyonu ya da sınıfı saran, davranışını orijinal kodu değiştirmeden genişleten higher-order fonksiyon. `@decorator` sözdizimi ile uygulanır' FROM q
UNION ALL
  SELECT id, 2, 'Sadece sınıf metodlarında kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Decorator performansı düşürür' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'mid', 'Generator ile list comprehension arasındaki bellek farkı nedir?', '`[x*2 for x in range(1_000_000)]` tüm listeyi RAM''e yükler. `(x*2 for x in range(1_000_000))` bir generator object döner; her `next()` çağrısında bir değer üretir. `sum()`, `for` döngüsü gibi iterable bekleyen yerlerde generator kullanmak belleği ciddi ölçüde azaltır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynı belleği kullanır' FROM q
UNION ALL
  SELECT id, 1, 'List comprehension tüm listeyi bellekte oluşturur. Generator expression (`(x for x in ...)`) lazy''dir; değerleri birer birer üretir, büyük veri setlerinde belleği korur' FROM q
UNION ALL
  SELECT id, 2, 'Generator her zaman daha yavaştır' FROM q
UNION ALL
  SELECT id, 3, 'Generator''lar yalnızca sayılar için kullanılabilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'mid', 'Mutable default argument tuzağı nedir?', '`def append_to(elem, lst=[]):` çağrısında `lst` varsayılanı her çağrıda aynı liste objesidir. Her çağrıda öğe eklenir ve birikim oluşur. Çözüm: `def append_to(elem, lst=None): if lst is None: lst = []`. Bu Python''da çok sık karşılaşılan bir tuzaktır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Default argümanların değiştirilememesi' FROM q
UNION ALL
  SELECT id, 1, 'Fonksiyon tanımında `def f(lst=[])` gibi mutable bir default değer kullanıldığında, bu nesne tüm çağrılar arasında paylaşılır ve istem dışı birikime yol açar' FROM q
UNION ALL
  SELECT id, 2, 'Sadece sözlükler için geçerlidir' FROM q
UNION ALL
  SELECT id, 3, 'Python 3''te bu sorun giderilmiştir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'junior', '`*args` ve `**kwargs` ne işe yarar?', '`def f(*args, **kwargs)` → `f(1, 2, a=3)` çağrısında `args=(1,2)`, `kwargs={"a":3}` olur. Aynı zamanda unpack operatörü olarak kullanılır: `f(*liste, **sozluk)`. Wrapper/decorator yazarken ve esnek API tasarımında yaygındır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Sadece built-in fonksiyonlarda kullanılır' FROM q
UNION ALL
  SELECT id, 1, '`*args`: pozisyonel argümanları tuple olarak toplar. `**kwargs`: isimli argümanları dict olarak toplar. Her ikisi de değişken sayıda argüman almayı sağlar' FROM q
UNION ALL
  SELECT id, 2, '`**kwargs` yalnızca sözlük argümanları için kullanılır' FROM q
UNION ALL
  SELECT id, 3, '`*args` maksimum 10 argüman alabilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'mid', 'Context manager (`with` statement) ve `__enter__`/`__exit__` nasıl çalışır?', '`with open("f") as f:` → `open()` dönen objenin `__enter__`''ı çağrılır (dosyayı açar), blok bittikten sonra `__exit__` otomatik kapanır. `contextlib.contextmanager` decorator''ı ile generator fonksiyondan da context manager oluşturulabilir. Exception handling''i de yönetebilir.', 1, true)
  RETURNING id
)
