  SELECT id, 0, 'Yalnızca dosya işlemleri için kullanılır' FROM q
UNION ALL
  SELECT id, 1, '`with` bloğuna girildiğinde `__enter__` çağrılır, blok bittiğinde (hata olsa da olmasa da) `__exit__` çağrılır. Kaynak yönetimini (dosya, DB bağlantısı, lock) güvenli yapar' FROM q
UNION ALL
  SELECT id, 2, '`__exit__` sadece hata durumunda çalışır' FROM q
UNION ALL
  SELECT id, 3, 'Context manager oluşturmak için sınıf yazmak şarttır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'mid', '`@property` decorator''ı nasıl çalışır?', '`@property` ile `def radius(self)` tanımlanırsa `obj.radius` (parantez olmadan) çağrılır. `@radius.setter` ile `obj.radius = 5` intercepted edilir; doğrulama eklenir. Bu sayede API değişmeden internal implementasyon değiştirilebilir (encapsulation).', 1, true)
  RETURNING id
)
