WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('python', 'tr', 'junior', '`isinstance()` ve `type()` eşitlik kontrolü arasındaki fark nedir?', '`class B(A): pass` → `b = B()` için `isinstance(b, A)` → True, `type(b) == A` → False. Duck typing ve polymorphism için `isinstance()` tercih edilir. Python standart kütüphanesi de `isinstance()` kullanır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynı sonucu verir' FROM q
UNION ALL
  SELECT id, 1, '`isinstance(obj, cls)` kalıtımı dikkate alır (alt sınıf da True döner). `type(obj) == cls` yalnızca tam eşleşmeye bakar; alt sınıflar False verir' FROM q
UNION ALL
  SELECT id, 2, '`type()` daha doğrudur' FROM q
UNION ALL
  SELECT id, 3, '`isinstance()` yalnızca primitive tipler için çalışır' FROM q;

