UNION ALL
  SELECT id, 2, 'Lazy evaluation yalnızca parallelStream''de çalışır' FROM q
UNION ALL
  SELECT id, 3, 'Stream bir kez tüketildikten sonra yeniden kullanılabilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('java', 'tr', 'mid', '`ArrayList` ve `LinkedList` ne zaman tercih edilmeli?', 'ArrayList dinamik array''dir: index erişimi O(1) ama ekleme/silme O(n) (kaydırma). LinkedList çift yönlü bağlı liste: baş/son eklemesi O(1) ama get O(n). Pratikte ArrayList modern donanımda cache-friendly olduğundan genellikle daha hızlıdır. LinkedList yalnızca çok sık ekleme/silme yapılan senaryolarda avantaj sağlar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Her zaman ArrayList tercih edilmeli' FROM q
UNION ALL
  SELECT id, 1, 'ArrayList: random access (get) O(1), ortaya ekleme O(n). LinkedList: başa/ortaya ekleme/silme O(1) (node referansı biliniyorsa), random access O(n). Çoğu durumda ArrayList daha iyi cache locality sunar' FROM q
UNION ALL
  SELECT id, 2, 'LinkedList her zaman daha hızlıdır' FROM q
UNION ALL
  SELECT id, 3, 'İkisi de tamamen aynı performansı sunar' FROM q;

