WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', 'C#''ta value type ve reference type arasındaki fark nedir?', 'Value type''lar (int, double, struct, enum): stack''te saklanır, atama değeri kopyalar. Reference type''lar (class, string, array): heap''te saklanır, atama referansı paylaşır. Nullable<T> (veya `int?`) ile value type''lar null olabilir. struct küçük, sık kullanılan, immutable veri için idealdir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de heap''te saklanır' FROM q
UNION ALL
  SELECT id, 1, 'Value type (struct, int, bool): stack''te saklanır, kopyalama değeri kopyalar. Reference type (class, interface, delegate): heap''te saklanır, kopyalama referansı kopyalar' FROM q
UNION ALL
  SELECT id, 2, 'Reference type''lar daha hızlıdır' FROM q
UNION ALL
  SELECT id, 3, 'Value type''lar null olamaz' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', '`delegate` ve `event` arasındaki fark nedir?', '`event` anahtar kelimesi encapsulation sağlar: sınıf dışından `+=` ve `-=` ile abone olunabilir ama `=` ile direkt atama yapılamaz ve dışarıdan tetiklenemez. Delegate ise sadece bir tip tanımıdır. Observer/event pattern''de `event` kullanmak kapsamı korur.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi tamamen aynıdır' FROM q
UNION ALL
  SELECT id, 1, '`delegate` tip tanımıdır; metod referansı tutar ve doğrudan çağrılabilir, dışarıdan atanabilir (=). `event` delegate''i saran; sadece += / -= ile abone olunabilir, dışarıdan tetiklenemez' FROM q
UNION ALL
  SELECT id, 2, 'Event multicast desteklemez' FROM q
UNION ALL
  SELECT id, 3, 'Delegate yalnızca static metodlar için kullanılır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'senior', 'LINQ''de deferred execution (ertelenmiş çalıştırma) ne anlama gelir?', '`var q = list.Where(x => x > 0).Select(x => x*2)` → bu satırda hiç hesaplama olmaz. `foreach (var x in q)` veya `q.ToList()` çağrısında çalışır. Bu özellik, sorgu parametreleri sonradan değiştirilebileceğinden esneklik sağlar. `IQueryable` ile uzak veri kaynağına (DB) sorgu gönderilmeden önce optimize edilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'LINQ sorguları asla çalışmaz' FROM q
UNION ALL
  SELECT id, 1, 'Sorgu tanımlandığında değil, iterasyon başladığında (foreach, ToList(), Count() gibi) çalışır. Bu sayede zincir operasyonlar birleştirilir ve veri kaynağı son anda sorgulanır' FROM q
UNION ALL
  SELECT id, 2, 'Yalnızca LINQ to SQL''de geçerlidir' FROM q
UNION ALL
  SELECT id, 3, 'Deferred execution performansı düşürür' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', 'C#''ta `async/await` ve `Task` nasıl çalışır?', '`await httpClient.GetAsync(url)` → I/O tamamlanana kadar thread serbest bırakılır, diğer işler yapılır. Tamamlandığında devam edilir. `async void` exception''ları yakalanamaz, yalnızca event handler''lar için kullanılır. `ConfigureAwait(false)` ile context switch overhead azaltılır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Her async metod yeni bir thread oluşturur' FROM q
UNION ALL
  SELECT id, 1, '`async` metod, `await` ifadesinde I/O bekleme süresini caller thread''e geri verir; thread pool''u bloke etmez. `Task` asenkron operasyonun sonucunu temsil eder' FROM q
UNION ALL
  SELECT id, 2, '`async void` her zaman `async Task`''a tercih edilmelidir' FROM q
UNION ALL
  SELECT id, 3, 'await yalnızca network isteklerinde kullanılır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'senior', '`IEnumerable<T>` ile `IQueryable<T>` arasındaki fark nedir?', '`dbContext.Users.Where(u => u.Age > 18).ToList()` → IQueryable üzerinde `Where` SQL''e çevrilir; sadece uygun kayıtlar çekilir. Aynı sorgu `IEnumerable` üzerinde yapılsaydı tüm kayıtlar belleğe alınıp C#''ta filtre yapılırdı. ORM sorgularında IQueryable kritik performans farkı yaratır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de tamamen aynı şekilde çalışır' FROM q
UNION ALL
  SELECT id, 1, '`IEnumerable<T>`: in-memory collection''da LINQ operasyonlarını C#''ta çalıştırır. `IQueryable<T>`: expression tree oluşturur, provider (EF Core gibi) bunu SQL''e çevirir; filtreleme veritabanında yapılır' FROM q
UNION ALL
  SELECT id, 2, 'IQueryable yalnızca Entity Framework''te kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'IEnumerable daha hızlıdır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', 'C# 9+ `record` tipi ne sağlar?', '`record Person(string Name, int Age)` → constructor, property, Equals (içerik bazlı), GetHashCode, ToString otomatik üretilir. `var p2 = p1 with { Age = 30 }` ile kısmi kopyalama yapılır. Immutability ve value semantics gereken yerlerde (CQRS command/query nesneleri) class''a göre çok daha az kod gerektirir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Sadece veri tabanı kayıtlarını temsil etmek için kullanılır' FROM q
UNION ALL
  SELECT id, 1, 'Immutable referans tipi; value-based equality (içerik karşılaştırması), `with` expression ile kopyalama ve otomatik ToString sağlar. Özellikle DTO ve value object tasarımı için idealdir' FROM q
UNION ALL
  SELECT id, 2, 'Record''lar kalıtımı desteklemez' FROM q
UNION ALL
  SELECT id, 3, 'Record yalnızca struct olarak tanımlanabilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', '`ref` ve `out` parametreleri arasındaki fark nedir?', '`int.TryParse("42", out int result)` → out kullanımı: result önceden tanımlanmış olmak zorunda değil, TryParse mutlaka bir değer atar. `ref` ise metoda mevcut değeri gönderip geri almak için kullanılır. C# 7+ ile `out var result` sözdizimi kolaylık sağlar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynıdır' FROM q
UNION ALL
  SELECT id, 1, '`ref`: çağrı öncesi değişken initialize edilmiş olmalıdır, metod okuyabilir/yazabilir. `out`: initialize edilmemiş olabilir, metod mutlaka değer atamalıdır. İkisi de değeri referansla iletir' FROM q
UNION ALL
  SELECT id, 2, '`out` yalnızca return değeri için kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Modern C#''ta ikisi de gereksizdir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'junior', '`using` direktifi ve `using` statement arasındaki fark nedir?', 'Namespace import: `using System.Collections.Generic;`. Resource management: `using (var conn = new SqlConnection(cs)) {}` → blok bitiminde Dispose() otomatik çağrılır. C# 8 ile `using var conn = ...;` kullanıldığında scope sonunda otomatik dispose edilir. Her ikisi de farklı amaçlara hizmet eder.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi aynıdır' FROM q
UNION ALL
  SELECT id, 1, '`using System;` namespace import eder. `using (var r = new Resource())` IDisposable''ı otomatik dispose eder. C# 8+ ile `using var r = new Resource();` şeklinde blok kapsamında kullanılabilir' FROM q
UNION ALL
  SELECT id, 2, '`using` yalnızca unmanaged resource''lar için zorunludur' FROM q
UNION ALL
  SELECT id, 3, '`using statement` performance sorunlarına yol açar' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'mid', '`Action<T>`, `Func<T,TResult>` ve `Predicate<T>` farkları nelerdir?', '`Action<string>` → `void(string)` imzalı metod. `Func<int, int, string>` → `string(int, int)` imzalı metod. `Predicate<int>` → `bool(int)` imzalı metod, `Func<int, bool>`''a denktir. Bunlar generic delegate türleridir; lambda expression''larla birlikte kullanılan temel yapı taşlarıdır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Üçü de aynı şeydir' FROM q
UNION ALL
  SELECT id, 1, '`Action<T>`: void dönen delegate. `Func<T,TResult>`: değer dönen delegate (son tip dönüş tipi). `Predicate<T>`: bool dönen `Func<T,bool>` özel hali' FROM q
UNION ALL
  SELECT id, 2, 'Func yalnızca LINQ ile kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Action en fazla 4 parametre alabilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('csharp', 'tr', 'senior', 'Nullable reference type (`string?`) C# 8''de ne sağlar?', 'Nullable reference type''lar (.csproj''da `<Nullable>enable</Nullable>`) ile derleyici null akışını analiz eder. `string name` → null atanamaz (uyarı verir). `string? name` → null olabilir, kullanmadan önce kontrol gerekir. Bu sayede runtime NullReferenceException''ları büyük ölçüde derleme aşamasında önlenir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'String''lerin null olmasını tamamen engeller' FROM q
UNION ALL
  SELECT id, 1, 'Derleyiciye hangi referansların null olabileceğini bildirir; null dereference uyarısı alınır. `string` non-nullable, `string?` nullable anlamına gelir. NullReferenceException''ları derleme aşamasında yakalar' FROM q
UNION ALL
  SELECT id, 2, 'Runtime''da null kontrol ekler' FROM q
UNION ALL
  SELECT id, 3, 'Yalnızca value type''lar için çalışır' FROM q;

-- ── go (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'tr', 'mid', 'Goroutine, OS thread''den nasıl farklıdır?', 'OS thread''leri MB''larca stack ile başlar ve OS context switch maliyetine tabidir. Goroutine''ler 2KB ile başlar, gerektiğinde büyür. Go runtime, goroutine''leri OS thread''lerine GOMAXPROCS sayısınca eşler. `go func()` ile başlatmak son derece ucuzdur; binlerce goroutine normal karşılanır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Goroutine ve thread aynı şeydir' FROM q
UNION ALL
  SELECT id, 1, 'Goroutine''ler Go runtime tarafından yönetilen hafif eş zamanlılık birimleridir (2KB başlangıç stack). Binlerce goroutine az sayıda OS thread üzerinde M:N scheduling ile çalışır' FROM q
UNION ALL
  SELECT id, 2, 'Goroutine''ler CPU''yu paralel kullanamaz' FROM q
UNION ALL
  SELECT id, 3, 'Her goroutine ayrı bir CPU çekirdeğinde çalışır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'tr', 'mid', 'Buffered ve unbuffered channel arasındaki fark nedir?', 'Unbuffered channel, gönderici ve alıcının aynı anda hazır olmasını gerektirir — senkron iletişim, sinyalizasyon için idealdir. Buffered channel, üretici-tüketici senaryolarında akış kontrolü sağlar. Yanlış boyutlu buffer deadlock veya goroutine leak''e yol açabilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynı şekilde çalışır' FROM q
UNION ALL
  SELECT id, 1, 'Unbuffered (`make(chan T)`): gönderici, alıcı hazır olana kadar bloke olur (senkron randevu). Buffered (`make(chan T, n)`): kapasite dolana kadar gönderici bloke olmaz (asenkron)' FROM q
UNION ALL
  SELECT id, 2, 'Buffered channel daha güvenlidir' FROM q
UNION ALL
  SELECT id, 3, 'Unbuffered channel yalnızca goroutine içinde kullanılır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'tr', 'junior', '`defer` nasıl çalışır?', '`defer f.Close()` → fonksiyon ne zaman ve nasıl çıkarsa çıksın (normal return, panic) Close() çağrılır. Birden fazla defer LIFO''dur. defer''lerin argümanları tanımlandıkları anda evaluate edilir. Named return değerleri ile birlikte kullanılarak return değeri de değiştirilebilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Program başlangıcında çalışır' FROM q
UNION ALL
  SELECT id, 1, 'Defer''lenen fonksiyon, çevreleyen fonksiyon geri döndüğünde (return veya panic) LIFO sırasında çalışır. Kaynak temizleme (dosya kapatma, mutex unlock) için idealdir' FROM q
UNION ALL
  SELECT id, 2, 'Defer yalnızca goroutine''lerde kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Birden fazla defer tanımlanamaz' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'tr', 'junior', 'Go''da interface''ler nasıl implement edilir?', 'Go''da `implements` keyword''ü yoktur. `io.Reader` interface''i `Read(p []byte) (n int, err error)` metodunu gerektirir; bu metodu tanımlayan her tip otomatik olarak `io.Reader`''dır. Bu structural typing (duck typing) yaklaşımı bağımlılıkları azaltır ve test edilebilirliği artırır.', 1, true)
  RETURNING id
)
