  SELECT id, 2, 'Interface sadece pointer receiver ile implement edilebilir' FROM q
UNION ALL
  SELECT id, 3, 'Bir tip yalnızca tek bir interface implement edebilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'tr', 'mid', 'Go''da hata yönetiminin idiomatic yolu nedir?', '`f, err := os.Open("file"); if err != nil { return err }` Go''nun temel hata yönetimi kalıbıdır. `fmt.Errorf("wrap: %w", err)` ile hata sarmalanır. `errors.Is()` hata zincirinde belirli bir hatayı arar, `errors.As()` belirli bir tipe dönüştürür. Exception yerine explicit error değerleri, hata akışını görünür kılar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'try/catch/finally kullanmak' FROM q
UNION ALL
  SELECT id, 1, 'Fonksiyonlar son değer olarak `error` döndürür; çağıran `if err != nil` ile kontrol eder. `errors.New()`, `fmt.Errorf()` ve `errors.Is/As()` kullanılır' FROM q
UNION ALL
  SELECT id, 2, 'Panic her zaman hata için kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Error interface''i implement etmek zorunlu değildir' FROM q;

