  SELECT id, 1, 'Her değerin tek bir sahibi vardır. Sahip scope''tan çıkınca değer drop edilir. Sahiplik move ile devredilir; eski değişken geçersiz olur' FROM q
UNION ALL
  SELECT id, 2, 'Rust''ta bellek manuel olarak yönetilir' FROM q
UNION ALL
  SELECT id, 3, 'Ownership yalnızca heap verisi için geçerlidir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'senior', 'Borrowing ve reference''lar nasıl çalışır?', 'Borrow checker''ın temel kuralı: aynı scope''ta aynı veriye ya N tane `&T` (read-only) ya da tam olarak 1 tane `&mut T` (write) olabilir. Bu kural compile-time''da data race''i imkânsız kılar. Referanslar her zaman geçerli (dangling pointer yok) ve kural dışı erişim yok.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Rust''ta pointer kullanılamaz' FROM q
UNION ALL
  SELECT id, 1, 'Aynı anda ya birden fazla immutable reference (`&T`) ya da tek bir mutable reference (`&mut T`) olabilir; ikisi aynı anda kullanılamaz. Bu kural compile-time''da data race''i önler' FROM q
UNION ALL
  SELECT id, 2, 'Mutable reference sayısı sınırsızdır' FROM q
UNION ALL
  SELECT id, 3, 'Reference''lar ownership''i devreder' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'senior', 'Lifetime annotation (`''a`) nedir ve ne zaman gereklidir?', '`fn longest<''a>(x: &''a str, y: &''a str) -> &''a str` → dönüş referansı, x ve y''nin daha kısa süre yaşayanı kadar geçerlidir. Derleyici bunu compile-time''da doğrular; dangling reference imkânsız olur. Struct''ta `struct S<''a> { r: &''a str }` ile referans field tanımlanır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Rust''ta her referans için lifetime zorunludur' FROM q
UNION ALL
  SELECT id, 1, 'Derleyiciye referansların ne kadar süre geçerli olduğunu belirtir. Genellikle lifetime elision ile otomatik çıkarılır; birden fazla referans döndüren veya struct içinde referans tutan durumlarda açıkça yazılır' FROM q
UNION ALL
  SELECT id, 2, 'Lifetime yalnızca closure''larda kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Lifetime annotation runtime overhead ekler' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'mid', '`Option<T>` tipi null''ın yerine nasıl kullanılır?', '`fn find(id: u32) -> Option<User>` → bulunamazsa None. `if let Some(user) = find(1) { ... }` veya `match`, `unwrap_or_else`, `map`, `?` ile işlenir. `unwrap()` None''da panic yapar — production''da tercih edilmez. Bu yaklaşım NullPointerException''ı compile-time''da imkânsız kılar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Option yalnızca database işlemleri için kullanılır' FROM q
UNION ALL
  SELECT id, 1, 'Rust''ta null yoktur. `Option<T>` enum''u `Some(T)` (değer var) veya `None` (değer yok) durumlarını temsil eder. Pattern matching veya `?` operatörü ile güvenli biçimde işlenir' FROM q
UNION ALL
  SELECT id, 2, 'Option kullanmak zorunlu değildir' FROM q
UNION ALL
  SELECT id, 3, 'None değeri runtime''da otomatik handle edilir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'mid', '`Result<T, E>` ve `?` operatörü hata yönetimini nasıl kolaylaştırır?', '`let content = fs::read_to_string("f")?;` → hata olursa fonksiyondan `Err` ile erken döner. Zincirleme: `parse_config()?.validate()?.apply()?` ile her adım hata kontrolü yapılır. `From` trait''i ile farklı hata tipleri otomatik dönüştürülür. `anyhow` ve `thiserror` crate''leri hata yönetimini daha da kolaylaştırır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Result yalnızca I/O hataları için kullanılır' FROM q
UNION ALL
  SELECT id, 1, '`Result<T,E>` başarı (`Ok(T)`) veya hata (`Err(E)`) temsil eder. `?` operatörü `Err` ise erken dönüş yapar, `Ok` ise değeri açar; hata propagation''ı zincirlemeyi kolaylaştırır' FROM q
UNION ALL
  SELECT id, 2, '`?` operatörü panic''e yol açar' FROM q
UNION ALL
  SELECT id, 3, 'Result ve Option aynı tiptir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'mid', 'Trait nedir ve polymorphism nasıl sağlanır?', '`trait Animal { fn sound(&self) -> &str; }` → her implementor kendi versiyonunu sağlar. `fn make_sound(a: &impl Animal)` → static dispatch, monomorphized (zero-cost abstraction). `fn make_sound(a: &dyn Animal)` → vtable ile dynamic dispatch, farklı tipler aynı collection''da tutulabilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Trait yalnızca inheritance için kullanılır' FROM q
UNION ALL
  SELECT id, 1, 'Trait, paylaşılan davranışı tanımlar (interface''e benzer). Static dispatch (`impl Trait`, generics) ile zero-cost, dynamic dispatch (`dyn Trait`) ile runtime polymorphism sağlanır' FROM q
UNION ALL
  SELECT id, 2, 'Bir tip yalnızca tek trait implement edebilir' FROM q
UNION ALL
  SELECT id, 3, 'Trait''ler runtime overhead ekler' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'senior', '`Box<T>`, `Rc<T>` ve `Arc<T>` ne zaman kullanılır?', '`Box<T>` → stack''te büyük değeri veya recursive type''ı heap''e taşır. `Rc<T>` → birden fazla okuyucu olduğunda (single-thread); drop edilmesi için tüm referansların düşmesi gerekir. `Arc<T>` → thread''ler arası paylaşımlı sahiplik için (`Arc<Mutex<T>>` kombinasyonu yaygındır). Clone ile referans sayısı artar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Üçü de aynıdır' FROM q
UNION ALL
  SELECT id, 1, '`Box<T>`: heap allocation, tek sahip. `Rc<T>`: single-thread reference counting, çoklu sahip. `Arc<T>`: atomik reference counting, multi-thread güvenli çoklu sahiplik' FROM q
UNION ALL
  SELECT id, 2, 'Box yalnızca recursive type için kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Arc her zaman Rc yerine tercih edilmelidir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'mid', '`match` expression neden önemlidir?', '`match shape { Circle(r) => PI*r*r, Rect(w,h) => w*h }` → Rust tüm varyantların ele alındığını derleme aşamasında doğrular; unhandled case derleme hatası verir. `if let`, `while let` ise tek bir pattern için kısaltmadır. Destructuring, nested pattern ve `@` binding desteklenir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Sadece integer değerleri için kullanılır' FROM q
UNION ALL
  SELECT id, 1, 'Exhaustive pattern matching sağlar: tüm case''ler handle edilmezse derleme hatası verir. Enum varyantlarını, tuple''ları, struct''ları ve guard koşullarını desenlerle çözebilir' FROM q
UNION ALL
  SELECT id, 2, 'match switch''in başka bir yazım şeklidir' FROM q
UNION ALL
  SELECT id, 3, 'match yalnızca Option ve Result için kullanılır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'junior', '`&str` ve `String` arasındaki fark nedir?', '`"hello"` string literal → `&''static str`. `String::from("hello")` → heap allocation, owned. Fonksiyon parametresi olarak `&str` tercih edilir (hem literal hem String kabul eder). `&String` → `&str`''a coerce edilebilir. `to_string()` veya `to_owned()` ile `String` oluşturulur.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'İkisi de aynıdır' FROM q
UNION ALL
  SELECT id, 1, '`&str`: string dilimi, immutable borrowed referans (genellikle binary veya heap''e), sabit boyut. `String`: heap''te büyüyebilen, owned, mutable UTF-8 string' FROM q
UNION ALL
  SELECT id, 2, 'String daha hızlıdır' FROM q
UNION ALL
  SELECT id, 3, '&str yalnızca string literal''lerde kullanılır' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'tr', 'junior', 'Cargo ne işe yarar ve Rust ekosistemindeki rolü nedir?', '`cargo new`, `cargo build`, `cargo test`, `cargo run`, `cargo doc`. `Cargo.toml` → metadata ve bağımlılıklar. `Cargo.lock` → deterministik build. `cargo clippy` → linter, `cargo fmt` → formatter. crates.io, Rust''ın merkezi paket kayıt yeridir. Workspace ile monorepo yönetimi de desteklenir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Yalnızca bağımlılık yönetimi için kullanılır' FROM q
UNION ALL
  SELECT id, 1, 'Rust''ın resmi build sistemi ve paket yöneticisidir: derleme, test, bağımlılık yönetimi (crates.io), benchmark ve dokümantasyon üretimini tek araçta sunar' FROM q
UNION ALL
  SELECT id, 2, 'Cargo yalnızca open source projeler için kullanılabilir' FROM q
UNION ALL
  SELECT id, 3, 'Cargo Makefile''ın başka bir adıdır' FROM q;

-- ── fullstack (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'mid', 'SPA, SSR ve SSG arasındaki temel farklar nelerdir?', 'SPA (React/Vue): ilk yükleme ağır, sonraki navigasyonlar hızlı, SEO için ek çaba gerekir. SSR (Next.js, Nuxt): her request''te HTML hazır gelir, SEO güçlü, sunucu yükü artar. SSG: build time''da HTML üretilir, CDN''den sunulur, süper hızlı ama gerçek zamanlı içerik zor. ISR (Next.js) hibrit çözüm sunar.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Üçü de aynı şekilde çalışır' FROM q
UNION ALL
  SELECT id, 1, 'SPA: tarayıcıda render (SEO zayıf, hızlı navigasyon). SSR: her istekte sunucuda render (SEO güçlü, TTFB yavaş). SSG: build''de render (en hızlı TTFB, dinamik içerik sınırlı)' FROM q
UNION ALL
  SELECT id, 2, 'SSR yalnızca mobile uygulamalar için kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'SSG her zaman en iyi seçimdir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'senior', 'JWT token''ı frontend''de nerede saklamak en güvenlidir?', 'localStorage/sessionStorage → XSS saldırısıyla JS üzerinden okunabilir. HttpOnly cookie → JS erişemez (document.cookie''de görünmez), XSS''e karşı dayanıklı. Ek olarak `Secure` (HTTPS) ve `SameSite=Strict` flag''leri CSRF''i önler. Refresh token HttpOnly cookie''de, access token memory''de (kısa ömürlü) tutmak yaygın bir pattern''dir.', 2, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'localStorage — her yerden erişilebilir' FROM q
UNION ALL
  SELECT id, 1, 'URL parametresinde — kolayca paylaşılır' FROM q
UNION ALL
  SELECT id, 2, 'HttpOnly cookie: XSS ile çalınamaz (JS erişemez). CSRF koruması için SameSite=Strict/Lax veya CSRF token eklenir' FROM q
UNION ALL
  SELECT id, 3, 'sessionStorage — localStorage''dan daha güvenlidir' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'mid', 'REST ve GraphQL arasında ne zaman hangisi tercih edilmeli?', 'REST: HTTP caching (CDN), standart tool desteği, anlaşılır semantik. GraphQL: tek endpoint, istemci ihtiyacı kadar veri çeker (mobil bant genişliği tasarrufu), schema introspection, subscription. GraphQL''in karmaşıklık, N+1 sorunu (DataLoader ile çözülür) ve caching zorlukları da göz önünde bulundurulmalı.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'GraphQL her zaman daha iyidir' FROM q
UNION ALL
  SELECT id, 1, 'REST: basit CRUD, caching kritik, birden fazla istemci tipi yok. GraphQL: farklı istemcilerin farklı veri ihtiyacı, over/under-fetching sorunu, iç içe ilişkili veri' FROM q
UNION ALL
  SELECT id, 2, 'REST artık kullanılmamalıdır' FROM q
UNION ALL
  SELECT id, 3, 'GraphQL yalnızca mobil için uygundur' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'mid', 'CORS preflight request nedir ve ne zaman tetiklenir?', 'Simple request: GET/POST/HEAD + basit header''lar → direkt gönderilir. "Non-simple": PUT, DELETE, custom header (Authorization), JSON content-type → OPTIONS preflight tetiklenir. Sunucu `Access-Control-Allow-Origin`, `Access-Control-Allow-Methods` header''larıyla yanıt verir. Preflight başarısızsa asıl istek engellenir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Her HTTP isteğinde preflight gönderilir' FROM q
UNION ALL
  SELECT id, 1, 'Tarayıcı, "simple request" kriterlerini karşılamayan cross-origin isteklerden önce OPTIONS isteği gönderir; sunucu izin verirse asıl istek yapılır' FROM q
UNION ALL
  SELECT id, 2, 'Preflight yalnızca POST isteklerinde çalışır' FROM q
UNION ALL
  SELECT id, 3, 'Preflight server-side''da devre dışı bırakılamaz' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'senior', 'HTTP caching: `Cache-Control`, `ETag` ve `Last-Modified` nasıl çalışır?', '`Cache-Control: max-age=3600` → 1 saat tarayıcı cache. `no-cache` → her seferinde doğrulama yap. `no-store` → sakla. ETag: `If-None-Match: "abc"` ile sunucu değişmediyse 304 döner (body yok). `stale-while-revalidate` ile eski veri gösterilirken arka planda yenilenir. API response''ları için `private`, statik assets için `public, immutable` tercih edilir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'HTTP caching yalnızca CDN için geçerlidir' FROM q
UNION ALL
  SELECT id, 1, 'Cache-Control: max-age ile süre belirtir. ETag: içeriğin hash''i, koşullu istek (If-None-Match) ile 304 Not Modified alınır. Last-Modified: tarih bazlı doğrulama. İkisi de gereksiz veri transferini önler' FROM q
UNION ALL
  SELECT id, 2, 'Caching yalnızca GET isteklerinde çalışır' FROM q
UNION ALL
  SELECT id, 3, 'ETag ve Last-Modified aynı anda kullanılamaz' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'mid', 'WebSocket, Server-Sent Events (SSE) ve Long Polling arasındaki fark nedir?', 'WebSocket: chat, oyun, real-time collaboration — düşük latency, iki yönlü. SSE: hisse fiyatı, bildirim, log streaming — tek yönlü, HTTP/2 ile çoklu akış, otomatik reconnect. Long Polling: eski tarayıcı desteği gerektiğinde fallback. Socket.IO her üçünü de kapsayan transport agnostic kütüphanedir.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Üçü de aynı teknolojidir' FROM q
UNION ALL
  SELECT id, 1, 'WebSocket: çift yönlü, kalıcı bağlantı. SSE: sunucudan istemciye tek yönlü, HTTP üzerinden event stream. Long Polling: istemci, sunucu yanıt verene kadar bekler; döngülü istek yapar' FROM q
UNION ALL
  SELECT id, 2, 'SSE WebSocket''ten daha güçlüdür' FROM q
UNION ALL
  SELECT id, 3, 'Long Polling gerçek zamanlı için kullanılamaz' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'tr', 'mid', 'Database connection pooling neden önemlidir?', 'PostgreSQL''de her bağlantı ~5-10MB bellek kullanır. 1000 eş zamanlı request için 1000 bağlantı yerine pool (örn. 20 bağlantı) + kuyruk kullanılır. PgBouncer (PostgreSQL), HikariCP (Java), connection pool parametreleri: min/max pool size, connection timeout, idle timeout. Pool boyutu genellikle CPU core × 2-4 civarındadır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Yalnızca büyük uygulamalarda gereklidir' FROM q
UNION ALL
  SELECT id, 1, 'Her istek için yeni DB bağlantısı açmak pahalıdır (TCP handshake, auth). Pool, önceden açılmış bağlantıları paylaşır; latency azalır, DB üzerindeki max connection baskısı yönetilir' FROM q
UNION ALL
  SELECT id, 2, 'Connection pooling veri güvenliğini tehlikeye atar' FROM q
UNION ALL
  SELECT id, 3, 'Modern veritabanları pooling''e ihtiyaç duymaz' FROM q;

WITH q AS (
