  VALUES ('fullstack', 'tr', 'mid', 'Monorepo ve polyrepo yaklaşımlarının avantaj/dezavantajları nelerdir?', 'Google, Meta, Microsoft monorepo kullanır (Bazel, Nx, Turborepo ile). Monorepo: frontend/backend ortak tip tanımları, koordineli release, tek PR''da full-stack değişiklik. Polyrepo: microservice bağımsızlığı, küçük takımlar için net sınır. Nx ve Turborepo incremental build ile monorepo''nun ölçekleme sorununu azaltır.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Monorepo her zaman daha iyidir' FROM q
UNION ALL
  SELECT id, 1, 'Monorepo: paylaşılan kod, atomik değişiklik, birleşik CI — ama build süresi ve tooling karmaşıklığı artar. Polyrepo: servis bağımsızlığı, izole CI — ama kod paylaşımı ve cross-repo değişiklikler zorlaşır' FROM q
UNION ALL
  SELECT id, 2, 'Polyrepo yalnızca büyük şirketlerde kullanılır' FROM q
UNION ALL
  SELECT id, 3, 'Monorepo Git''i desteklemez' FROM q;

